	@Test
	public void executingADeletedSavedQueryAnswersAPageDataErrorRecord() throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			TestableQueryServlet pageServlet = new TestableQueryServlet();
			pageServlet.setRepository(repository);
			pageServlet.setCookieHandler(mock(CookieHandler.class));
			QueryStorage storage = mock(QueryStorage.class);
			when(storage.selectSavedQuery(anyString(), anyString(), eq("deleted-query")))
					.thenThrow(new BadRequestException("Could not find query entry in storage."));
			pageServlet.substituteQueryStorage(storage);
			MockHttpServletRequest rawRequest = new MockHttpServletRequest("POST", "/query");
			rawRequest.addHeader("Accept", "application/vnd.rdf4j.workbench-query-v2+ndjson");
			rawRequest.addParameter("action", "exec");
			rawRequest.addParameter("ref", "id");
			rawRequest.addParameter("query", "deleted-query");
			rawRequest.addParameter("owner", "");
			MockHttpServletResponse response = new MockHttpServletResponse();

			pageServlet.doPost(new WorkbenchRequest(repository, rawRequest, Map.of("queryLn", "SPARQL")), response);

			assertThat(response.getStatus()).isEqualTo(HttpServletResponse.SC_BAD_REQUEST);
			assertThat(response.getContentType()).startsWith("application/vnd.rdf4j.workbench-query-v2+ndjson");
			assertThat(response.getContentAsString()).contains("\"type\":\"error\"")
					.contains("Could not find query entry in storage.");
		} finally {
			repository.shutDown();
		}
	}

