	private void assertQueryLinkPrefillsTheQueryPage(String action) throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(SimpleValueFactory.getInstance().createIRI("urn:s"), RDF_TYPE,
					SimpleValueFactory.getInstance().createIRI("urn:T"));
		}
		try {
			TestableQueryServlet pageServlet = new TestableQueryServlet();
			pageServlet.setRepository(repository);
			pageServlet.setCookieHandler(mock(CookieHandler.class));
			MockHttpServletRequest rawRequest = new MockHttpServletRequest("GET", "/query");
			rawRequest.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
			if (action != null) {
				rawRequest.addParameter("action", action);
			}
			rawRequest.addParameter("queryLn", "SPARQL");
			rawRequest.addParameter("query", "SELECT * WHERE { <urn:s> ?p ?o }");
			MockHttpServletResponse response = new MockHttpServletResponse();

			pageServlet.service(new WorkbenchRequest(repository, rawRequest, Map.of("queryLn", "SPARQL")), response);

			String body = response.getContentAsString();
			assertThat(response.getStatus()).isEqualTo(HttpServletResponse.SC_OK);
			List<tools.jackson.databind.JsonNode> records = body.lines()
					.filter(line -> !line.isBlank())
					.map(line -> new tools.jackson.databind.ObjectMapper().readTree(line))
					.toList();
			assertThat(records).filteredOn(record -> "view".equals(record.path("type").asText()))
					.extracting(record -> record.path("id").asText())
					.containsExactly("query");
			assertThat(body).contains("SELECT * WHERE { <urn:s> ?p ?o }").doesNotContain("urn:T");
		} finally {
			repository.shutDown();
		}
	}

