	private static final IRI RDF_TYPE = org.eclipse.rdf4j.model.vocabulary.RDF.TYPE;

	private QueryStorage prepareSave(String savePrivate, String user) throws Exception {
		Repository repository = mock(Repository.class);
		when(repository.getValueFactory()).thenReturn(SimpleValueFactory.getInstance());
		servlet.setRepository(repository);
		RepositoryInfo repositoryInfo = new RepositoryInfo();
		repositoryInfo.setId("lmdb-store");
		servlet.setRepositoryInfo(repositoryInfo);
		QueryStorage storage = mock(QueryStorage.class);
		servlet.substituteQueryStorage(storage);
		when(storage.checkAccess(any())).thenReturn(true);
		when(storage.askExists(any(), eq("my-query"), any())).thenReturn(false);
		return storage;
	}

	private static WorkbenchRequest saveRequest(String savePrivate, String user) throws Exception {
		WorkbenchRequest request = mock(WorkbenchRequest.class);
		stubAction(request, "save");
		when(request.isParameterPresent(QueryServlet.QUERY)).thenReturn(true);
		when(request.getParameter(QueryServlet.QUERY)).thenReturn(SHORT_QUERY);
		when(request.getParameter("query-name")).thenReturn("my-query");
		when(request.getParameter("queryLn")).thenReturn("SPARQL");
		when(request.getParameter("limit_query")).thenReturn("100");
		when(request.getParameterValues("limit_query")).thenReturn(new String[] { "100" });
		when(request.getParameter("query-timeout")).thenReturn("17");
		when(request.getInt("query-timeout")).thenReturn(17);
		when(request.getParameter("overwrite")).thenReturn("false");
		when(request.isParameterPresent("save-private")).thenReturn(true);
		when(request.getParameter("save-private")).thenReturn(savePrivate);
		when(request.isParameterPresent("infer")).thenReturn(true);
		when(request.getParameter("infer")).thenReturn("true");
		when(request.getParameter("server-user")).thenReturn(user);
		return request;
	}

	private HttpServletResponse assertFeatureRequestAllowed(WorkbenchPolicy policy, Map<String, String> initParameters,
			String action, boolean post, Map<String, String> parameters) throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			TestableQueryServlet policyServlet = new TestableQueryServlet();
			policyServlet.setPolicy(policy, initParameters);
			policyServlet.setRepository(repository);
			policyServlet.setCookieHandler(mock(CookieHandler.class));
			MockHttpServletRequest rawRequest = new MockHttpServletRequest(post ? "POST" : "GET", "/query");
			rawRequest.addParameter("action", action);
			rawRequest.addParameter("query", SHORT_QUERY);
			parameters.forEach(rawRequest::addParameter);
			WorkbenchRequest request = new WorkbenchRequest(repository, rawRequest, Map.of("queryLn", "SPARQL"));
			HttpServletResponse response = mock(HttpServletResponse.class);
			when(response.getOutputStream()).thenReturn(new ByteArrayServletOutputStream());
			when(response.getWriter()).thenReturn(new PrintWriter(new StringWriter()));
			if (post) {
				policyServlet.doPost(request, response);
			} else {
				policyServlet.service(request, response);
			}

			verify(response, never()).sendError(HttpServletResponse.SC_FORBIDDEN);
			return response;
		} finally {
			repository.shutDown();
		}
	}

	private void assertFeatureRequestDenied(WorkbenchPolicy policy, String action, boolean post,
			Map<String, String> parameters) throws Exception {
		assertFeatureRequestDenied(policy, Map.of(), action, post, parameters);
	}

	private void assertFeatureRequestDenied(WorkbenchPolicy policy, Map<String, String> initParameters, String action,
			boolean post, Map<String, String> parameters) throws Exception {
		WorkbenchRequest request = mock(WorkbenchRequest.class);
		stubAction(request, action);
		when(request.getMethod()).thenReturn(post ? "POST" : "GET");
		when(request.isParameterPresent(QueryServlet.QUERY)).thenReturn(true);
		when(request.getParameter(QueryServlet.QUERY)).thenReturn(SHORT_QUERY);
		when(request.getParameter("queryLn")).thenReturn("SPARQL");
		when(request.getParameter("explain")).thenReturn("Optimized");
		when(request.getParameter("explain-format")).thenReturn("text");
		when(request.isParameterPresent("explain")).thenReturn(false);
		when(request.isParameterPresent("Accept")).thenReturn(false);
		when(request.getHeader("Accept-Encoding")).thenReturn(null);
		when(request.getContextPath()).thenReturn("");
		parameters.forEach((name, value) -> {
			when(request.isParameterPresent(name)).thenReturn(true);
			when(request.getParameter(name)).thenReturn(value);
		});
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			TestableQueryServlet policyServlet = new TestableQueryServlet();
			policyServlet.setPolicy(policy, initParameters);
			policyServlet.setRepository(repository);
			policyServlet.setCookieHandler(mock(CookieHandler.class));
			HttpServletResponse response = mock(HttpServletResponse.class);
			when(response.getOutputStream()).thenReturn(new ByteArrayServletOutputStream());
			when(response.getWriter()).thenReturn(new PrintWriter(new StringWriter()));
			if (post) {
				policyServlet.doPost(request, response);
			} else {
				policyServlet.service(request, response);
			}

			verify(response).sendError(HttpServletResponse.SC_FORBIDDEN);
		} finally {
			repository.shutDown();
		}
	}

